		if c.DeletedAt != nil && c.DeletedAt.Before(cutoff) {
			delete(s.customers, id)
			n++
		}
	}
	return n
}

// unindexEmail removes c's email address from the index, if c holds it. The caller holds the lock.
func (s *Store) unindexEmail(c Customer) {
	key := customerEmailKey(c.OrgID, c.Email)
	if s.customersByEmail[key] == c.ID {
		delete(s.customersByEmail, key)
	}
}

