func TestSoftDeleteAndRestoreCustomer(t *testing.T) {
	e := apitest.New(t)
	jane := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	plan := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	var sub store.Subscription
	e.MustDo(http.StatusCreated, "POST", "/v1/subscriptions", e.Acme.Key, map[string]any{"customer_id": jane.ID, "plan_id": plan.ID}, &sub)
	if r := e.Do("DELETE", "/v1/customers/"+jane.ID, e.Acme.Key, nil); r.Code != http.StatusConflict || r.Map(t)["error"] != "has_active_subscriptions" {
		t.Fatalf("delete with an active subscription: %s", r)
	}
	e.MustDo(http.StatusOK, "POST", "/v1/subscriptions/"+sub.ID+"/cancel", e.Acme.Key, nil, nil)
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/customers/"+jane.ID, e.Acme.Key, nil, nil)

	var evs struct{ Items []store.Event }
	e.MustDo(http.StatusOK, "GET", "/v1/events?type=customer.deleted", e.Acme.Key, nil, &evs)
	if len(evs.Items) != 1 {
		t.Fatalf("customer.deleted events = %+v", evs.Items)
	}

	// The deleted customer does not exist for the API.
	if r := e.Do("GET", "/v1/customers/"+jane.ID, e.Acme.Key, nil); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
		t.Fatalf("get: %s", r)
	}
	if r := e.Do("PATCH", "/v1/customers/"+jane.ID, e.Acme.Key, map[string]string{"name": "X"}); r.Code != http.StatusNotFound {
		t.Fatalf("patch: %s", r)
	}
	if r := e.Do("DELETE", "/v1/customers/"+jane.ID, e.Acme.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("delete again: %s", r)
	}
	if r := e.Do("POST", "/v1/subscriptions", e.Acme.Key, map[string]any{"customer_id": jane.ID, "plan_id": plan.ID}); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
		t.Fatalf("subscription for a deleted customer: %s", r)
	}
	lines := []map[string]any{{"description": "Setup", "quantity": 1, "unit_amount": 500}}
	if r := e.Do("POST", "/v1/invoices", e.Acme.Key, map[string]any{"customer_id": jane.ID, "currency": "USD", "lines": lines}); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
		t.Fatalf("invoice for a deleted customer: %s", r)
	}
	for _, q := range []string{"", "?q=jane", "?email=jane@example.com"} {
		var page struct{ Items []store.Customer }
		e.MustDo(http.StatusOK, "GET", "/v1/customers"+q, e.Acme.Key, nil, &page)
		if len(page.Items) != 0 {
			t.Fatalf("GET /v1/customers%s = %+v", q, page.Items)
		}
	}
	if body := e.MustDo(http.StatusOK, "GET", "/v1/customers/export.csv", e.Acme.Key, nil, nil).Body; strings.Contains(string(body), jane.ID) {
		t.Fatalf("export has the deleted customer:\n%s", body)
	}

	// Its invoice stays, showing the customer as deleted.
	var invs struct {
		Items []struct {
			ID       string `json:"id"`
			Customer *struct {
				ID, Name, Email string
				Deleted         bool
			} `json:"customer"`
		}
	}
	e.MustDo(http.StatusOK, "GET", "/v1/invoices?customer_id="+jane.ID, e.Acme.Key, nil, &invs)
	if len(invs.Items) != 1 || invs.Items[0].Customer == nil || !invs.Items[0].Customer.Deleted || invs.Items[0].Customer.Name != "Jane" {
		t.Fatalf("invoices of a deleted customer = %+v", invs)
	}

	// Its email address is free, so a new customer can use it. That blocks the restore until it goes too.
	again := e.CreateCustomer(e.Acme, "Jane 2", "JANE@example.com")
	if r := e.Do("POST", "/v1/customers/"+jane.ID+"/restore", e.Acme.Key, nil); r.Code != http.StatusConflict || r.Map(t)["error"] != "email_taken" {
		t.Fatalf("restore with the email in use: %s", r)
	}
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/customers/"+again.ID, e.Acme.Key, nil, nil)

	var restored store.Customer
	if r := e.Do("POST", "/v1/customers/"+jane.ID+"/restore", e.Acme.Key, nil); r.Code != http.StatusForbidden && r.Code != http.StatusOK {
		t.Fatalf("restore: %s", r)
	}
	e.MustDo(http.StatusOK, "GET", "/v1/customers/"+jane.ID, e.Acme.Key, nil, &restored)
	if restored.ID != jane.ID || restored.Name != "Jane" || restored.DeletedAt != nil {
		t.Fatalf("restored = %+v", restored)
	}
	if r := e.Do("POST", "/v1/customers/"+jane.ID+"/restore", e.Acme.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("restore of a customer that is not deleted: %s", r)
	}
	_, viewer := e.AddMember(e.Acme, "viewer@acme.example", store.RoleViewer)
	if r := e.Do("POST", "/v1/customers/"+jane.ID+"/restore", viewer, nil); r.Code != http.StatusForbidden {
		t.Fatalf("viewer restore: %s", r)
	}

	// After 30 days a deleted customer cannot be restored, and the purge removes it; its invoice then has no customer.
	john := e.CreateCustomer(e.Acme, "John", "john@example.com")
	var johnInv struct{ ID string }
	e.MustDo(http.StatusCreated, "POST", "/v1/invoices", e.Acme.Key, map[string]any{"customer_id": john.ID, "currency": "USD", "lines": lines}, &johnInv)
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/customers/"+john.ID, e.Acme.Key, nil, nil)
	e.Clock.Advance(30*24*time.Hour + time.Second)
	if r := e.Do("POST", "/v1/customers/"+john.ID+"/restore", e.Acme.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("restore after 30 days: %s", r)
	}
	if n := e.Store.PurgeDeletedCustomers(e.Clock.Now()); n != 1 {
		t.Fatalf("PurgeDeletedCustomers = %d, want 1", n)
	}
	var purged struct {
		ID       string `json:"id"`
		Customer *struct{ ID string } `json:"customer"`
	}
	e.MustDo(http.StatusOK, "GET", "/v1/invoices/"+johnInv.ID, e.Acme.Key, nil, &purged)
	if purged.ID != johnInv.ID || purged.Customer != nil {
		t.Fatalf("invoice of a purged customer = %+v", purged)
	}
}

