	}
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/api-keys/"+k.ID, e.Acme.Key, nil, nil)
	if r := e.Do("GET", "/v1/org", k.Token, nil); r.Code != http.StatusUnauthorized {
		t.Fatalf("revoked key: %s", r)
	}
}

func TestOrgSettings(t *testing.T) {
